"""Apply the completed module to the captured LING406 interface."""
from pathlib import Path
import re,json
import build_template as ui
ROOT=ui.ROOT
base=(ui.BASE/'app.js').read_text()
def original(name):
 lines=base.splitlines();i=next(i for i,l in enumerate(lines) if l.startswith(f'function {name}('));j=i+1
 if not lines[i].endswith('}'):
  while lines[j]!='}':j+=1
  j+=1
 return '\n'.join(lines[i:j])
for name in ['guide','core','experiments','test','quizzes','missed','written']:
 content=original(name).replace('all nine collections','all six collections').replace('all nine uploaded lectures','all six collections')
 content=content.replace('100-question','60-question').replace('18 multipart prompts','12 multipart prompts').replace('20 original questions per lecture','10 original questions per collection').replace('20-question','10-question')
 content=content.replace("Coverage spans every collection, with additional questions allocated by the supplied review's emphasis.",'Ten questions cover each collection, including earlier-course concepts in the supplied final review.')
 ui.replace_function(name,content)
ui.replace_function('home',r'''function home(){const count=D.sections.filter(s=>state.read[s.id]).length;return `<span class="tag">MODULE III · FINAL</span><div class="hero"><span class="tag">LING406 · PSYCHOLINGUISTICS</span><h1>Reading, morphology,<br>thought and modality.</h1><p>Study the original slides beside clear teaching explanations. Compare the experiments, distinguish the models, and practice explaining what the evidence means.</p><div class="row"><button class="primary" data-lecture="reading1">Begin with Reading 1</button><button data-go="guide">Open the study guide</button><button data-go="test">Take the current practice test</button></div></div><div class="grid"><div class="card"><span class="tag">CURRENT FOCUS</span><h2>Module III</h2><p>Five lecture collections and the 52-page final review · 185 original pages · four teaching editions · 60 practice questions.</p><p class="small muted">${count} of 185 pages marked read</p><div class="progress"><span style="width:${count/185*100}%"></span></div><button data-go="combined">Open combined notes</button></div><div class="card"><span class="tag">EXPERIMENTS & MODELS</span><h2>Explain what the evidence means</h2><p>Follow the task, comparison and result, then explain what distinguishes the competing accounts.</p><div class="row"><button data-go="experiments">Experiments to know</button><button data-go="core">Core review</button></div></div><div class="card"><span class="tag">COURSE MODULES</span><h2>Module II · Midterm 2</h2><p>Return to speech perception, sentence processing, aphasia, development and language learning.</p><a class="button" href="../?view=home">Open Module II</a></div></div><div class="card"><h2>Read it. Teach it. Try it.</h2><p>Choose a teaching edition, explain the source visual aloud, then reveal feedback on a practice question. Your notes stay attached to the same page across editions and views.</p><div class="row"><button data-go="quizzes">Choose a collection quiz</button><button data-review>Open final review</button><button data-go="written">Written practice</button></div></div><p class="small muted">Practice questions are original study material based on the supplied files. They are not instructor exam questions.</p>`}''')
ui.replace_function('collection',r'''function collection(){const m=modules.get(selected),items=m.sections.map(id=>sections.get(id)),source=D.sources[m.source];return `<span class="tag">INDIVIDUAL COLLECTION ${m.number}</span><h1>${esc(m.title)}</h1><p>${items.length} original pages in source order, with four teaching editions, personal notes and read marks.</p><div class="row study-tools"><button data-reader="lecture">Visual + transcript</button>${expandButton('lecture')}<button data-quiz="lecture:${m.id}">10-question collection quiz</button><a class="button" href="${source.file}" target="_blank" rel="noopener">Open original ${source.format.toUpperCase()}</a>${source.format==='pptx'?`<a class="button" href="${source.pdf}" target="_blank" rel="noopener">Open PDF rendition</a>`:''}</div>${searchTools('Search this collection')}${items.map(sectionHTML).join('')}`}''')
ui.replace_function('sources',r'''function sources(){return `<h1>Sources & coverage</h1><p>Six supplied files cover 185 pages, including every title and assignment page. The final review is labeled 2025 and includes earlier-course topics as well as Weeks 10–12.</p><div class="row study-tools"><button data-action="export">Export Module III notes & progress</button><a class="button" href="coverage-report.json">Coverage report</a><a class="button" href="source-manifest.json">Source manifest</a></div><div class="grid">${D.modules.map(m=>{const s=D.sources[m.source];return `<div class="card"><h2>${esc(m.title)}</h2><p>${s.pages} original pages · four teaching editions · 10 questions.</p><a href="${s.file}">${esc(s.original)}</a>${s.format==='pptx'?`<p><a href="${s.pdf}">PDF rendition, including hidden slides</a></p>`:''}<br><button data-lecture="${m.id}">Open collection</button></div>`}).join('')}</div><h2>Teaching editions</h2><div class="card"><p>PSYC301 v20-style teaching connects the concept, supporting explanation and interpretation. Original C Version 2 gives a concise explanation in source order. D Version 2 reframes the key distinction directly. Original C Version 3 adds important visual labels and comparisons.</p><p>The editions share checked source facts and supporting explanations. Their framing and depth differ. Title, assignment and noninstructional pause pages retain their visuals without invented teaching.</p><p>The final review keeps independent notes and original visuals. Matching lecture explanations are reused only for the corresponding material. Other review topics have their own explanations.</p></div><h2>Practice and study emphasis</h2><div class="card"><p>The 60-question test contains ten questions from each collection. It is a Module III practice set, not a prediction of the entire final exam. Core review includes supplied-review matches and concepts needed to understand them.</p><p>The 2025 review is used as supplied course material. It is not presented as a confirmed current exam blueprint. Original audio and video links are retained where supplied. External availability may change.</p><p>Module I contains Lectures 1–10 and the Midterm 1 review. Module II keeps its existing content and browser progress. Progress in Module III stays in this browser and can be exported above.</p></div>`}''')
ui.replace_function('sourceCaption',r'''function sourceCaption(s){const source=D.sources[s.source];return `<figcaption class="source-caption">${source.format==='pptx'?'PowerPoint PDF rendition':'Original source'} · page ${s.page}<br><a href="${source.pdf}#page=${s.page}" target="_blank" rel="noopener">Open matching PDF page</a> · <a href="${source.file}" target="_blank" rel="noopener">${esc(source.original)}</a></figcaption>`}''')
ui.replace_function('visual',r'''function visual(s,eager=false){const source=D.sources[s.source];return `<figure class="section-visual reader-visual"><button class="slide-button" data-image="${esc(s.image)}" data-pdf="${source.pdf}#page=${s.page}" aria-label="Enlarge ${esc(displayTitle(s))}, page ${s.page}"><img class="slide" src="${s.image}" alt="${esc(displayTitle(s))} · source page ${s.page}" loading="${eager?'eager':'lazy'}" decoding="async"></button>${sourceCaption(s)}${mediaFor(s)}</figure>`}''')
# Functional module switcher in every reader and the persistent top bar.
ui.app=ui.app.replace("function readerControls(){return `<div class=\"reader-controls\">", "function readerControls(){return `<div class=\"reader-controls\">${moduleSelector()}")
ui.app=ui.app.replace("pending('Experiment videos')",'videoGallery()')
ui.app=ui.app.replace("const entry=D.editions[state.transcriptVersion-20].scripts[s.id];\n if(entry.status==='pending')return '<p class=\"small muted\">Teaching explanation pending. This template keeps original source text separate from authored explanations.</p>';", "const entry=D.editions[state.transcriptVersion-20].scripts[s.id];")
ui.app=re.sub(r'\nfunction pending\(title\).*?\n', '\n',ui.app)
ui.app=ui.app.replace("document.querySelector('header .transcript-version').outerHTML=transcriptSelector();", "document.querySelector('header .transcript-version').outerHTML=moduleSelector()+transcriptSelector();")
ui.app=ui.app.replace('data-transcript-version aria-label="Transcript version"','data-transcript-version aria-label="Transcript version"')
ui.app += r'''
function moduleSelector(){return ''}
const sourceMedia=[
 {section:'m3-reading1-p004',title:'Finnish spelling and pronunciation',url:'http://tasteoffinnish.fi/lesson1-1/',kind:'Original linked lesson'},
 {section:'m3-modalities-p004',title:'Sign language in action',url:'https://www.youtube.com/watch?v=8J_UfLH8isU',kind:'Original linked video'},
 {section:'m3-modalities-p012',title:'Tic-tac gesture comparison',url:'https://www.youtube.com/watch?v=YsZu_wZa-j8',kind:'Original linked video'}
];
function mediaFor(s){const mapped=D.coverage.reviewMappings[String(s.page)],id=s.source==='review'&&mapped?mapped:s.id;return sourceMedia.filter(m=>m.section===id).map(m=>`<p><a class="button" href="${m.url}" target="_blank" rel="noopener">${esc(m.kind)} · ${esc(m.title)}</a></p>`).join('')}
function videoGallery(){return `<h1>Experiment videos & source demonstrations</h1><p>Open the demonstrations linked in the supplied material, then return to the matching source and explanation.</p><div class="grid">${sourceMedia.map(m=>`<article class="card"><h2>${esc(m.title)}</h2><p>${esc(m.kind)}</p><div class="row"><a class="button" href="${m.url}" target="_blank" rel="noopener">Open source demonstration</a><button data-open-section="${m.section}">Matching slide + explanation</button></div></article>`).join('')}</div><p class="small muted">These are external source links, not recordings recovered from the PDFs. Other experiments are explained with their original source figures in Experiments to know.</p><button data-go="experiments">Open experiments</button>`}
document.addEventListener('change',e=>{if(e.target.matches('[data-course-module]')&&e.target.value==='2'){stopAudio();location.href='../?view=home'}});
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});
'''
# sourceMedia must be initialized before initial render, which can be a collection.
ui.app=ui.app.replace("const sourceMedia=[", "var sourceMedia=[")
initial="window.LingStudio={state,sections,modules,questions,startQuiz,go,openReader,validateAnswerKey:QZ.validateAnswerKey};document.querySelector('header .transcript-version').outerHTML=moduleSelector()+transcriptSelector();render();clock();"
assert initial in ui.app
ui.app=ui.app.replace(initial,'')+'\n'+initial+'\n'
(ROOT/'app.js').write_text(ui.app)
html=(ROOT/'index.html').read_text().replace('MODULE III · TEMPLATE','MODULE III').replace('Module III template','Module III · Study Studio')
html=html.replace('src="data.js"','src="data.js?v=module3-1"').replace('src="app.js"','src="app.js?v=module3-1"')
html=html.replace('</body>', '<script src="../module-navigation.js?v=modules-2" defer></script></body>')
html=html.replace('app.js?v=module3-1','app.js?v=module1-available-1')
(ROOT/'index.html').write_text(html)
print('Built release interface with working guides, experiments, quizzes and module switching.')
